/// What the API reads from.
#[derive(Clone)]
pub struct ApiState {
    /// Message bytes.
    pub blobs: Arc<dyn BlobStore>,
    /// Metadata.
    pub store: Arc<dyn Store>,
    /// Search.
    pub index: Arc<dyn SearchIndex>,
    /// Sign-in.
    pub auth: Arc<Auth>,
    /// Adding, syncing and importing mail.
    pub mailboxes: Arc<dyn Mailboxes>,
    /// The archive ledger.
    pub operations: Arc<dyn Operations>,
    /// Alias services and their keys.
    pub aliases: Arc<dyn Aliases>,
    /// Remote images for the reader's proxy.
    pub fetcher: Arc<dyn Fetcher>,
    /// Mark the session cookie `Secure` on every response, for instances served over https.
    /// Without it the cookie is `Secure` only when `X-Forwarded-Proto` is `https`.
    pub secure_cookies: bool,
    /// Message insights; `None` when the server runs no insights runner.
    pub insights: Option<InsightsConfig>,
    /// The instance switches for writing, from the `[write]` config.
    pub write: WriteSwitches,
    /// The outbox and transports; `None` when the server sends no mail, and every sending route
    /// answers `503`.
    pub sending: Option<Sending>,
    /// App passwords: who they sign in, and revoking them.
    pub devices: Arc<dyn DeviceAuth>,
    /// What the `[serve]` config says about devices and proxies.
    pub serve: ServeOptions,
    /// What rules tell outside the API: paused flows, `notify` and `webhook` actions.
    pub rule_hooks: Arc<dyn RuleHooks>,
}

/// The API routes under `/api`, and Thunderbird autoconfig at
/// `/.well-known/autoconfig/mail/config-v1.1.xml` and `/mail/config-v1.1.xml`.
///
/// State-changing requests must be `application/json` (uploads `application/octet-stream`) and, when they carry an `Origin`, come
/// from the same host; others are refused with `415` and `403`. Routes other than
/// `/api/session`, `/api/setup`, `/api/login`, `/api/logout`, `/api/openapi.json`, the one-time
/// profile download `/api/devices/profile/{token}`, autoconfig and the Web Push receiver `/api/push/dav/{id}` (which takes any body and needs no session) answer `401`
/// without a live session; unknown paths under `/api/` answer `404` to signed-in users.
pub fn router(state: ApiState) -> Router {
    let state = Arc::new(state);
    let protected = Router::new()
        .route(
            "/api/archives",
            get(routes::list_archives).post(manage::create_archive),
        )
        .route(
            "/api/archives/{id}",
            get(routes::get_archive)
                .patch(manage::update_archive)
                .delete(manage::delete_archive),
        )
        .route(
            "/api/archives/{id}/accounts",
            get(manage::list_accounts).post(manage::add_imap_account),
        )
        .route(
            "/api/archives/{id}/imports",
            post(manage::import_file).layer(DefaultBodyLimit::disable()),
        )
        .route(
            "/api/accounts/{id}",
            patch(manage::update_account).delete(manage::delete_account),
        )
        .route(
            "/api/archives/{id}/accounts/jmap",
            post(manage::add_jmap_account),
        )
        .route("/api/accounts/{id}/sync", post(manage::sync_account))
        .route(
            "/api/accounts/{id}/capabilities",
            get(write::get_capabilities).put(write::put_capabilities),
        )
        .route(
            "/api/users/{id}/grants/{archive}",
            put(write::put_grant).delete(write::delete_grant),
        )
        .route("/api/audit", get(write::list_audit))
        .route(
            "/api/devices",
            get(devices::list_devices).post(devices::create_device),
        )
        .route("/api/devices/setup", get(devices::device_setup))
        .route(
            "/api/devices/{id}/profile",
            post(client_setup::profile_link),
        )
        .route("/api/devices/serving", get(serving::serving))
        .route(
            "/api/devices/local-flags",
            get(serving::local_flags).delete(serving::drop_local_flags),
        )
        .route(
            "/api/devices/{id}",
            patch(devices::update_device).delete(devices::revoke_device),
        )
        .route("/api/rules/catalogue", get(rules::catalogue))
        .route(
            "/api/archives/{id}/flows",
            get(rules::list_flows).post(rules::create_flow),
        )
        .route("/api/archives/{id}/flows/test", post(rules::test_new_flow))
        .route(
            "/api/archives/{id}/flows/preview",
            post(rules::preview_template),
        )
        .route(
            "/api/flows/{id}",
            get(rules::get_flow)
                .put(rules::save_flow)
                .patch(rules::change_flow)
                .delete(rules::delete_flow),
        )
        .route("/api/flows/{id}/versions", get(rules::flow_versions))
        .route("/api/flows/{id}/test", post(rules::test_flow))
        .route("/api/flows/{id}/run", post(rules::run_manual))
        .route("/api/flows/{id}/runs", get(rules::flow_runs))
        .route("/api/flow-runs/{id}", get(rules::get_run))
        .route(
            "/api/flow-runs/{id}/actions/{index}/confirm",
            post(rules::confirm_action),
        )
        .route(
            "/api/flow-runs/{id}/actions/{index}/dismiss",
            post(rules::dismiss_action),
        )
        .route(
            "/api/archives/{id}/transports",
            get(send::list_transports).post(send::create_transport),
        )
        .route(
            "/api/transports",
            get(send::list_instance_transports).post(send::create_instance_transport),
        )
        .route(
            "/api/transports/{id}",
            patch(send::update_transport).delete(send::delete_transport),
        )
        .route(
            "/api/transports/{id}/grants",
            put(send::put_transport_grants),
        )
        .route("/api/transports/{id}/check", post(send::check_transport))
        .route(
            "/api/archives/{id}/identities",
            get(send::list_identities).post(send::create_identity),
        )
        .route(
            "/api/archives/{id}/identities/suggestions",
            get(send::identity_suggestions),
        )
        .route(
            "/api/identities/{id}",
            patch(send::update_identity).delete(send::delete_identity),
        )
        .route("/api/identities/{id}/users", put(send::put_identity_users))
        .route(
            "/api/archives/{id}/default-identity",
            put(send::put_default_identity),
        )
        .route(
            "/api/archives/{id}/drafts",
            get(drafts::list_drafts).post(drafts::create_draft),
        )
        .route(
            "/api/drafts/{id}",
            get(drafts::get_draft)
                .put(drafts::save_draft)
                .delete(drafts::delete_draft),
        )
        .route("/api/drafts/{id}/versions", get(drafts::draft_versions))
        .route(
            "/api/drafts/{id}/reverse-alias",
            post(drafts::reverse_alias),
        )
        .route(
            "/api/drafts/{id}/attachments",
            post(drafts::upload_attachment)
                .layer(DefaultBodyLimit::max(drafts::MAX_ATTACHMENT + 1)),
        )
        .route("/api/drafts/{id}/send", post(outbox::send_draft))
        .route("/api/messages/{id}/reply", post(drafts::reply))
        .route("/api/messages/{id}/forward", post(drafts::forward))
        .route("/api/archives/{id}/outbox", get(outbox::list_outbox))
        .route("/api/outbox/{id}", get(outbox::get_outbox))
        .route("/api/outbox/{id}/undo", post(outbox::undo))
        .route("/api/outbox/{id}/cancel", post(outbox::cancel))
        .route("/api/outbox/{id}/retry", post(outbox::retry))
        .route("/api/outbox/{id}/resend", post(outbox::resend))
        .route("/api/oauth/providers", get(oauth::providers))
        .route("/api/oauth/start", post(oauth::start))
        .route("/api/oauth/finish", post(oauth::finish))
        .route(
            "/api/users",
            get(people::list_users).post(people::create_user),
        )
        .route(
            "/api/users/{id}",
            patch(people::update_user).delete(people::delete_user),
        )
        .route("/api/me", patch(people::update_me))
        .route("/api/me/password", post(people::change_password))
        .route("/api/archives/{id}/folders", get(routes::list_folders))
        .route("/api/archives/{id}/labels", get(routes::list_labels))
        .route("/api/archives/{id}/messages", get(routes::list_messages))
        .route("/api/archives/{id}/search", get(routes::search))
        .route(
            "/api/archives/{id}/insights/status",
            get(insights::insights_status),
        )
        .route("/api/insights/data", get(insights_data::insights_data))
        .route("/api/archives/{id}/categories", get(categories::categories))
        .route(
            "/api/archives/{id}/category-overrides",
            get(categories::list_category_overrides).put(categories::put_category_override),
        )
        .route(
            "/api/archives/{id}/category-overrides/{override}",
            delete(categories::delete_category_override),
        )
        .route("/api/archives/{id}/export", get(export::export))
        .route(
            "/api/archives/{id}/contacts/export",
            get(export::export_contacts),
        )
        .route(
            "/api/archives/{id}/calendar/export",
            get(export::export_calendar),
        )
        .route("/api/messages/{id}", get(routes::get_message))
        .route(
            "/api/messages/{id}/changes",
            post(mail_changes::change_message),
        )
        .route("/api/messages/{id}/restore", post(mail_changes::restore))
        .route("/api/mail/changes", post(mail_changes::change_bulk))
        .route(
            "/api/mail-changes/{id}/retry",
            post(mail_changes::retry_change),
        )
        .route(
            "/api/mail-changes/{id}/dismiss",
            post(mail_changes::dismiss_change),
        )
        .route(
            "/api/accounts/{id}/mail-changes",
            get(mail_changes::list_mail_changes),
        )
        .route(
            "/api/accounts/{id}/retention",
            get(mail_changes::get_retention).put(mail_changes::put_retention),
        )
        .route("/api/messages/{id}/body", get(routes::get_body))
        .route("/api/messages/{id}/raw", get(routes::get_raw))
        .route("/api/messages/{id}/pdf", get(routes::get_pdf))
        .route(
            "/api/messages/{id}/unsubscribe",
            post(unsubscribe::unsubscribe),
        )
        .route(
            "/api/messages/{id}/attachments/{ordinal}",
            get(routes::get_attachment),
        )
        .route(
            "/api/messages/{id}/attachments/{ordinal}/thumbnail",
            get(routes::get_thumbnail),
        )
        .route("/api/messages/{id}/remote/{key}", get(remote::get_remote))
        .route("/api/messages/{id}/live/{key}", get(remote::get_live))
        .route(
            "/api/archives/{id}/remote-images",
            post(manage::start_remote_images),
        )
        .route("/api/tasks", get(tasks::list_tasks))
        .route("/api/ledger", get(ledger::get_ledger))
        .route("/api/archives/{id}/deletions", post(deletion::review))
        .route("/api/deletions/{id}/confirm", post(deletion::confirm))
        .route("/api/smtp", get(smtp::status))
        .route("/api/alias-providers", get(aliases::alias_providers))
        .route(
            "/api/archives/{id}/aliases",
            get(aliases::list_aliases).post(aliases::add_manual_alias),
        )
        .route(
            "/api/archives/{id}/aliases/{address}",
            patch(aliases::update_alias).delete(aliases::remove_alias),
        )
        .route(
            "/api/archives/{id}/alias-services",
            post(aliases::add_alias_service),
        )
        .route(
            "/api/archives/{id}/alias-strategies",
            get(aliases::list_alias_strategies).put(aliases::set_alias_strategy),
        )
        .route(
            "/api/alias-services/{id}",
            patch(aliases::update_alias_service).delete(aliases::remove_alias_service),
        )
        .route(
            "/api/alias-services/{id}/sync",
            post(aliases::sync_alias_service),
        )
        .route(
            "/api/alias-services/{id}/options",
            get(aliases::alias_options),
        )
        .route(
            "/api/alias-services/{id}/aliases",
            post(aliases::create_alias),
        )
        .route("/api/webhooks", get(webhooks::list).post(webhooks::create))
        .route(
            "/api/webhooks/{id}",
            patch(webhooks::update).delete(webhooks::remove),
        )
        .route("/api/webhooks/{id}/secret", post(webhooks::rotate))
        .route("/api/webhooks/{id}/test", post(webhooks::test))
        .route("/api/webhooks/{id}/deliveries", get(webhooks::deliveries))
        .route("/api/ledger/verify", post(ledger::verify_ledger))
        .route(
            "/api/sync-schedule",
            get(tasks::get_sync_schedule).put(tasks::set_sync_schedule),
        )
        .route("/api/tasks/{id}/cancel", post(tasks::cancel_task))
        .route(
            "/api/image-proxy",
            get(tasks::get_image_proxy).put(tasks::set_image_proxy),
        )
        .route("/api/threads/{id}", get(routes::get_thread))
        .route("/api/archives/{id}/collections", get(pim::list_collections))
        .route("/api/archives/{id}/contacts", get(pim::list_contacts))
        .route("/api/archives/{id}/events", get(pim::list_events))
        .route(
            "/api/items/{id}",
            get(pim::get_item).merge(delete(pim_edit::delete_item).layer(from_fn(write::detached))),
        )
        .route("/api/items/{id}/edit", get(pim_edit::get_edit))
        .route(
            "/api/items/{id}/content",
            put(pim_edit::edit_item).layer(from_fn(write::detached)),
        )
        .route(
            "/api/items/{id}/rsvp",
            get(invitations::rsvp_item_options)
                .merge(post(invitations::rsvp_item).layer(from_fn(write::detached))),
        )
        .route(
            "/api/messages/{id}/rsvp",
            get(invitations::rsvp_message_options)
                .merge(post(invitations::rsvp_message).layer(from_fn(write::detached))),
        )
        .route(
            "/api/messages/{id}/itip/apply",
            post(invitations::apply_itip).layer(from_fn(write::detached)),
        )
        .route(
            "/api/collections/{id}/organizing",
            get(invitations::organizing),
        )
        .route(
            "/api/collections/{id}/items",
            post(pim_edit::create_item).layer(from_fn(write::detached)),
        )
        .route(
            "/api/collections/{id}/write-mode",
            get(pim_edit::get_write_mode).put(pim_edit::put_write_mode),
        )
        .route("/api/pim/changes", get(pim_edit::list_changes))
        .route("/api/pim/changes/{id}/diff", get(pim_edit::change_diff))
        .route(
            "/api/pim/changes/{id}/resolve",
            post(pim_edit::resolve_change),
        )
        .route("/api/people/{id}/card", put(pim_edit::edit_person_card))
        .route("/api/archives/{id}/people", get(persons::list_people))
        .route("/api/people/{id}", get(persons::get_person))
        .route("/api/people/{id}/split", post(overrides::split))
        .route("/api/people/join", post(overrides::join))
        .route(
            "/api/people/overrides/{id}",
            delete(overrides::remove_override),
        )
        .route(
            "/api/archives/{id}/people/overrides",
            get(overrides::list_overrides),
        )
        .route("/api/archives/{id}/calendar", get(calendar::calendar))
        .route(
            "/api/archives/{id}/search/items",
            get(calendar::search_items),
        )
        .route("/api/events/{id}", get(calendar::get_event))
        .route(
            "/api/items/{id}/versions/{number}/raw",
            get(pim::get_version_raw),
        )
        .route("/api/{*rest}", any(routes::unknown))
        .route_layer(from_fn_with_state(state.clone(), write::idempotency))
        .route_layer(from_fn_with_state(state.clone(), access::check))
        .route_layer(from_fn_with_state(state.clone(), session::require_session));
    Router::new()
        .route("/api/session", get(session::current))
        .route(
            "/api/setup",
            get(session::setup_status).post(session::setup),
        )
        .route("/api/login", post(session::login))
        .route("/api/logout", post(session::logout))
        .route("/api/openapi.json", get(routes::openapi))
        .route("/api/oauth/callback", get(oauth::callback))
        .route(
            "/.well-known/autoconfig/mail/config-v1.1.xml",
            get(client_setup::autoconfig),
        )
        .route("/mail/config-v1.1.xml", get(client_setup::autoconfig))
        .merge(protected)
        .layer(from_fn(session::guard_writes))
        .merge(Router::new().route(
            "/api/push/dav/{id}",
            post(push::receive).layer(DefaultBodyLimit::max(push::MAX_MESSAGE)),
        ))
        .merge(
            Router::new().route(
                "/api/devices/profile/{token}",
                get(client_setup::profile_page)
                    .post(client_setup::download_profile)
                    .layer(DefaultBodyLimit::max(client_setup::MAX_CONFIRM)),
            ),
        )
        .with_state(state)
}

/// The OpenAPI description of [`router`] as pretty JSON.
pub fn openapi_json() -> String {
    ApiDoc::openapi()
        .to_pretty_json()
        .expect("the OpenAPI description serializes")
}

